input.command:
cat > ../sf2.js <<'EOF'
await page.goto('https://www.snowflake.com/en/customers/all-customers/?tags=content-type%2Fcase-study&tags=industry%2Ffinancial-services',{waitUntil:'networkidle'});
await page.waitForTimeout(3000);
const seen=new Map();
for(let i=0;i<6;i++){
  const r=await page.evaluate(()=>[...document.querySelectorAll('a[href*="/all-customers/"]')].filter(a=>/\/(case-study|video|snapshot)\//.test(a.href)).map(a=>a.href+'|'+a.innerText.trim().replace(/\s+/g,' ').slice(0,80)));
  r.forEach(x=>seen.set(x.split('|')[0],x));
  const n=page.getByText('Next',{exact:true}).first();
  if(!(await n.count())||!(await n.isVisible())) break;
  await n.click(); await page.waitForTimeout(2500);
}
console.log(seen.size); [...seen.values()].forEach(x=>console.log(x));
EOF
firecrawl scrape "https://www.snowflake.com/en/customers/all-customers/" -o /dev/null >/dev/null; firecrawl interact --timeout 200 --code "$(cat ../sf2.js)" -o sffs2.txt >/dev/null 2>&1; head -1 sffs2.txt; cut -c1-130 sffs2.txt | tail -n +2

